script:
// Anterior abdomen (patient's right = viewer's left): liver, gallbladder, bile ducts, four laparoscopic ports.
const PORTS = [[214, 446], [228, 200], [142, 366], [100, 404]];   // umbilical, epigastric, two right subcostal
const RUNGS = [["I", "Clean"], ["II", "Clean\ncontaminated"], ["III", "Contaminated"], ["IV", "Dirty"]];
const RY = i => 174 + i * 68;   // rung top
let el = {};
function txt(api, g, s, x, y, o) {
  const t = api.el("text", {x, y, "text-anchor": o.anchor || "start", "dominant-baseline": "central", "font-size": o.size || 18, "font-weight": o.weight || 800,
    fill: o.color || "#16323a", "font-family": "system-ui,sans-serif"}, g);
  if (o.halo) api.set(t, {stroke: "#fff", "stroke-width": 5, "paint-order": "stroke", "stroke-linejoin": "round"});
  String(s).split("\n").forEach((ln, i, a) => { const sp = api.el("tspan", {x, dy: i ? (o.size || 18) * 1.15 : -(a.length - 1) * (o.size || 18) * 0.575}, t); sp.textContent = ln; });
  return t;
}
function vis(api, node, o) { api.set(node, {opacity: o.toFixed(3), display: o > 0.001 ? "inline" : "none"}); }
function setup(api) {
  const liver = api.$("#liver"), P = liver.parentNode;
  const top = api.el("g", {}, P);   // above the liver
  // bile ducts + gallbladder
  el.ducts = api.el("g", {}, top);
  api.el("path", {d: "M214 282 C 224 292, 234 292, 238 300 M230 250 L238 300 L244 372", fill: "none", stroke: "#2d5a1c", "stroke-width": 9, "stroke-linecap": "round", "stroke-linejoin": "round"}, el.ducts);
  api.el("path", {d: "M214 282 C 224 292, 234 292, 238 300 M230 250 L238 300 L244 372", fill: "none", stroke: "#6fae4a", "stroke-width": 5.5, "stroke-linecap": "round", "stroke-linejoin": "round"}, el.ducts);
  el.gb = api.el("path", {d: "M166 334 C 150 322, 156 300, 178 292 C 194 286, 206 280, 214 280 C 220 284, 218 292, 210 300 C 200 312, 188 334, 166 334 Z",
    fill: "url(#gbG)", stroke: "#2d5a1c", "stroke-width": 2.5, filter: "url(#kit-volume)"}, top);
  el.glow = api.el("path", {d: "M166 334 C 150 322, 156 300, 178 292 C 194 286, 206 280, 214 280 L238 300 L244 372 M230 250 L238 300", fill: "none", stroke: "#ffd166", "stroke-width": 16, "stroke-linecap": "round", "stroke-linejoin": "round", opacity: 0}, top);
  top.insertBefore(el.glow, el.ducts);
  // instrument from the right subcostal port to the gallbladder
  el.inst = api.el("g", {}, top);
  api.el("path", {d: "M142 366 L168 326", stroke: "#6c7a80", "stroke-width": 6, "stroke-linecap": "round"}, el.inst);
  api.el("path", {d: "M168 326 L176 316 M168 326 L180 322", stroke: "#3d4a50", "stroke-width": 3.5, "stroke-linecap": "round"}, el.inst);
  // ports
  el.ports = PORTS.map(([x, y], i) => { const g = api.el("g", {}, top);
    const h = i < 2 ? 9 : 7;
    api.el("path", {d: "M" + (x - h) + " " + y + " H" + (x + h), stroke: "#7a3b2e", "stroke-width": 4.5, "stroke-linecap": "round"}, g);
    api.el("path", {d: "M" + (x - h + 2) + " " + (y - 3) + " H" + (x + h - 2), stroke: "#f6d6c4", "stroke-width": 1.5, "stroke-linecap": "round"}, g); return g; });
  el.navel = api.el("ellipse", {cx: 214, cy: 446, rx: 4, ry: 2, fill: "none"}, top);
  const ui = api.$("#ui");
  el.lab1 = api.el("g", {}, ui);
  api.el("path", {d: "M246 334 L274 356", stroke: "#2d5a1c", "stroke-width": 2.5}, el.lab1);
  txt(api, el.lab1, "Biliary tract", 264, 368, {color: "#2d5a1c", halo: true});
  el.lab0 = txt(api, ui, "4 ports", 252, 436, {color: "#5f7a80", halo: true, size: 17});
  // beat 2: controlled
  el.ring = api.el("circle", {cx: 200, cy: 310, r: 62, fill: "none", stroke: "@good", "stroke-width": 4, "stroke-dasharray": "10 8"}, ui);
  el.ok = api.el("g", {}, ui);
  api.el("rect", {x: 112, y: 474, width: 204, height: 36, rx: 18, fill: "#e8f6f3", stroke: "@good", "stroke-width": 2}, el.ok);
  txt(api, el.ok, "✓ No significant spill", 214, 492, {anchor: "middle", color: "#1d6f66", size: 17});
  // ladder
  const lad = api.el("g", {}, ui);
  txt(api, lad, "Wound class", 502, 152, {anchor: "middle", size: 18});
  el.rungs = RUNGS.map(([n, s], i) => { const g = api.el("g", {}, lad), y = RY(i);
    const r = api.el("rect", {x: 404, y, width: 192, height: 58, rx: 12, fill: "#f3f7f7", stroke: "#dbe6e7", "stroke-width": 2}, g);
    const b = api.el("circle", {cx: 430, cy: y + 29, r: 17, fill: "#5f7a80"}, g);
    txt(api, g, n, 430, y + 30, {anchor: "middle", color: "#fff", size: n.length > 2 ? 14 : 16});
    const tt = txt(api, g, s, 456, y + 30, {size: 17, color: "#5f7a80"});
    return {g, r, b, tt}; });
  el.mark = api.el("path", {d: "M382 0 L398 0 M390 -8 L398 0 L390 8", stroke: "@accent", "stroke-width": 4, fill: "none", "stroke-linecap": "round", "stroke-linejoin": "round"}, ui);
  el.hi = api.el("rect", {x: 404, y: RY(0), width: 192, height: 58, rx: 12, fill: "none", stroke: "@accent", "stroke-width": 3.5}, ui);
}
function render(t, api) {
  // 1. instrument reaches the gallbladder; the biliary tract is entered
  const ins = api.seg(t, 150, 800, "ease_out");
  vis(api, el.inst, ins); api.set(el.inst, {transform: "translate(" + (-(1 - ins) * 20).toFixed(1) + " " + ((1 - ins) * 30).toFixed(1) + ")"});
  const gl = api.seg(t, 800, 1400);
  api.set(el.glow, {opacity: (gl * (0.55 + 0.2 * Math.sin(t / 250)) * (1 - 0.6 * api.seg(t, 4600, 5000))).toFixed(3)});
  vis(api, el.lab1, api.seg(t, 1000, 1400) * (1 - api.seg(t, 2300, 2500)));
  vis(api, el.lab0, 1 - api.seg(t, 2300, 2500));
  // 2. controlled, no significant spill
  const r = api.seg(t, 2400, 3200, "ease_in_out");
  vis(api, el.ring, r); api.set(el.ring, {r: (80 - 18 * r).toFixed(1)});
  vis(api, el.ok, api.seg(t, 3100, 3500));
  // 3. ladder settles on class II; the port wounds are marked
  const m = api.seg(t, 4650, 5300, "ease_in_out");
  const y = RY(0) + 29 + m * 68;
  vis(api, el.mark, api.seg(t, 4600, 4800)); api.set(el.mark, {transform: "translate(0 " + y.toFixed(1) + ")"});
  vis(api, el.hi, api.seg(t, 4600, 4800)); api.set(el.hi, {y: (y - 29).toFixed(1)});
  const on = api.seg(t, 5200, 5500);
  const R2 = el.rungs[1];
  api.set(R2.r, {fill: api.mixColor("#f3f7f7", "#fff1ec", on)});
  api.set(R2.b, {fill: api.mixColor("#5f7a80", "#e76f51", on)});
  api.set(R2.tt, {fill: api.mixColor("#5f7a80", "#b23a1e", on)});
  el.ports.forEach((p, i) => { const c = p.firstChild; const k = api.seg(t, 4700 + i * 100, 5100 + i * 100);
    api.set(c, {stroke: api.mixColor("#7a3b2e", "#e76f51", k), "stroke-width": (4.5 + k * 2).toFixed(1)}); });
}
